    /// #363: the reconciler owns both the declared edge and the provenance
    /// citation for it. An empty replacement set retires the relation without
    /// touching another relation's entry or an ordinary row.
    #[tokio::test]
    async fn reconcile_retires_edge_sources_with_the_edge() {
        let dir = std::env::temp_dir().join(format!("ns-reconcile-prov-{}", uuid::Uuid::new_v4()));
        let store = LadybugStore::for_testing(&dir, 4).expect("open temp database");
        store.init("probe").await.expect("init");
        let v = vec![0.1, 0.2, 0.3, 0.4];
        for id in ["target-b", "target-c"] {
            store
                .upsert(
                    "probe",
                    id,
                    v.clone(),
                    retired_test_payload("fact", "agent", json!({})),
                )
                .await
                .unwrap();
        }
        store
            .upsert(
                "probe",
                "declarer",
                v.clone(),
                retired_test_payload(
                    "rule",
                    "agent",
                    json!({"related_to": ["target-b"], "governs": ["target-c"]}),
                ),
            )
            .await
            .unwrap();
        store
            .upsert(
                "probe",
                "ordinary",
                v,
                retired_test_payload("fact", "agent", json!({})),
            )
            .await
            .unwrap();

        let removed = store
            .reconcile_declared_edges("probe", "declarer", "RELATES_TO", &[])
            .await
            .unwrap();
        assert_eq!(removed, 1);

        let (_, head) = store
            .get("probe", "declarer")
            .await
            .unwrap()
            .expect("declarer exists");
        let sources = head.metadata["edge_sources"]
            .as_array()
            .expect("edge_sources array");
        assert!(
            !sources.iter().any(|s| s["rel_type"] == "RELATES_TO"),
            "the retired relation's provenance must go: {sources:?}"
        );
        assert!(
            sources
                .iter()
                .any(|s| s["rel_type"] == "GOVERNS" && s["resolved_target"] == "target-c"),
            "another relation's provenance must survive: {sources:?}"
        );
        let edges = store.list_edges("probe").await.unwrap();
        assert!(
            !edges
                .iter()
                .any(|(from, rel, _, _)| from == "declarer" && rel == "RELATES_TO"),
            "the declared RELATES_TO edge must be retired: {edges:?}"
        );
        assert!(
            edges.iter().any(|(from, rel, to, _)| from == "declarer"
                && rel == "GOVERNS"
                && to == "target-c"),
            "the unrelated edge must survive: {edges:?}"
        );
        let (_, ordinary) = store
            .get("probe", "ordinary")
            .await
            .unwrap()
            .expect("ordinary row exists");
        assert!(
            ordinary.metadata.get("edge_sources").is_none(),
            "an ordinary row must not gain provenance: {:?}",
            ordinary.metadata
        );
        let _ = std::fs::remove_dir_all(&dir);
    }

    async fn assert_f6_evidence_id_hash(hash_field: &str, hash: &str, expected: &str) {
        let store = retired_test_store().await;
        let v = vec![0.1, 0.2, 0.3, 0.4];
        store
            .upsert(
                "probe",
                "target-node",
                v.clone(),
                retired_test_payload("fact", "agent", json!({})),
            )
            .await
            .unwrap();

        let mut metadata = json!({
            "governs": ["target-node"],
            "absolute_path": "src/a.rs",
            "source": "src/a.rs"
        });
        metadata[hash_field] = json!(hash);
        let mut declarer = retired_test_payload("rule", "agent", metadata);
        declarer.location = "src/a.rs".to_string();
        declarer.location_lines = "3-4".to_string();
        store
            .upsert("probe", "declaring-rule", v, declarer)
            .await
            .expect("persist declaration and its resolved edge");

        let evidence_ids = store
            .with_conn(|conn| {
                let rows = conn.query(
                    "MATCH (a:Memory {id: 'declaring-rule'})-[r:GOVERNS]->(b:Memory {id: 'target-node'}) RETURN r.evidence_id",
                )?;
                Ok(rows.map(|row| format!("{}", row[0])).collect::<Vec<_>>())
            })
            .await
            .unwrap();
        assert_eq!(evidence_ids, vec![expected.to_string()]);

        let (_, payload) = store
            .get("probe", "declaring-rule")
            .await
            .unwrap()
            .expect("persisted declaration");
        let sources = payload.metadata["edge_sources"].as_array().unwrap();
        assert_eq!(sources.len(), 1);
        assert_eq!(sources[0]["evidence_id"], expected);
        assert_eq!(sources[0]["content_hash"], hash);
        assert_eq!(sources[0]["file"], "src/a.rs");
        assert_eq!(sources[0]["line_start"], 3);
        assert_eq!(sources[0]["line_end"], 4);
    }

